# Search for submission results after the submission time
import json

session_log = "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference/play/users/u014/system/state/sessions/01a19342-81a8-766b-a0b7-3cf267017720.jsonl"

with open(session_log, 'r') as f:
    lines = f.readlines()

# Find submission and subsequent results
for i, line in enumerate(lines):
    msg = json.loads(line)
    ts = msg.get('timestamp', '')
    typ = msg.get('type', '')

    # Look for messages with task result feedback after 18:50:00
    try:
        ts_obj = ts.replace('Z', '+00:00')
        from datetime import datetime
        ts_dt = datetime.fromisoformat(ts_obj)

        if ts_dt > datetime(2026, 10, 31, 18, 50, 0):
            # Check if this message has task result info
            if typ == 'message' or typ == 'toolResult':
                msg_str = str(msg).lower()
                if 'isCorrect' in msg_str or 'truth' in msg_str or 'result' in msg_str:
                    if typ == 'toolResult':
                        content = msg.get('message', {}).get('content', [])
                        content_str = str(content)
                        if 'isCorrect' in content_str or 'correct' in content_str or 'incorrect' in content_str or 'true' in content_str:
                            print(f"=== FOUND RESULT at {ts} ===")
                            print(f"Message: {content_str[:1000]}")
                            print(f"Full msg: {msg}")
                    elif typ == 'message':
                        print(f"=== At {ts}: {typ} ===")
                        msg_content = msg.get('message', {}).get('content', [])
                        if hasattr(msg_content, '__iter__') and not isinstance(msg_content, str):
                            for item in msg_content:
                                if isinstance(item, dict) and item.get('type') == 'text':
                                    if 'isCorrect' in item.get('text', '').lower() or 'truth' in item.get('text', '').lower():
                                        print(f"=== POSSIBLE RESULT at {ts} ===")
                                        print(f"Text: {item.get('text')[:1000]}")
    except Exception as e:
        pass

print("\n=== DONE searching ===")
